/* ===== SOURCE: repair-kb-internal-cases-20260907.js ===== */
'use strict';

// 萬里內部現場案例。這些數字/現象只代表當次實機，不是原廠通用規格。
// 用途：提供「症狀→實測→排除→結論」的現場思路；精確規格仍回到該機 Service Manual。
(function(){
  addRepairKB({
    id:'case-110xi4-ribbon-sensor-field',brand:'Zebra',models:['110Xi4'],
    title:'【內部實機案例】110Xi4 開機／FEED 即 Ribbon Out，Ribbon Sensor 讀值固定',
    category:'內部實機案例／Sensor',severity:'已實測',
    summary:'實機在開機或按 FEED 即報 Ribbon Out；清潔、設定與校正均無法解除。拔除 Ribbon Sensor 白色 5-pin 接頭後，開機校正可完整跑完且不再報錯；接回即復發，故障高度收斂到 Ribbon Sensor／其線路，而不是先判主板。',
    keyFacts:['當次實機 Ribbon Sensor 顯示值曾固定約 65；此數字不可當作所有 110Xi4 的正常/異常標準。','拔除 Ribbon Sensor 接頭後可完成校正，接回即報錯，是本案例最有判斷力的 A/B 證據。','本案例曾量到其中一腳約 4.80 V；Pin 定義與標準電壓未以 Service Manual 核對前，不可複製成通用規格。'],
    engineering:['已做過異丙醇清潔碳帶/紙張感應器、Printhead、Platen，無改善。','已切換 Direct Thermal / Thermal Transfer、內外碳與感應器相關設定；讀值仍固定。','曾發送短校正/重置 ZPL 後重啟，單獨不能消除 Ribbon Out；真正有區別的測試是 Sensor 接頭插拔。'],
    verify:['更換/修復 Sensor 或線束後，接回 Sensor 仍可正常開機','FEED/Calibration 可完整完成','Ribbon Out 不再誤報','以碳帶實際列印連續驗證'],
    flow:[['重現原始症狀','確認開機或 FEED 即 Ribbon Out，且碳帶實際存在。',['已重現','無法重現'],'先保存原始狀態。'],['排設定與清潔','Print Method、Ribbon 路徑、Sensor 清潔與 Calibration。',['仍報錯','已恢復'],'已恢復則不進硬體。'],['觀察 Ribbon Sensor 讀值','遮擋/移動碳帶時讀值是否固定或幾乎不變。',['固定/無變化','有明顯變化'],'本案例為固定。'],['斷電做接頭 A/B','拔除 Ribbon Sensor 接頭後再做基準開機/校正；再接回比較。',['拔除正常、接回異常','沒有差異'],'本案例為前者。'],['收斂零件','優先查 Ribbon Sensor、5-pin 線束/接頭；確認正常後才考慮主板輸入。',['Sensor/線束方向高','主板方向仍待查'],'不要把當次電壓數字當通用值。']],
    sources:['zebra_xi4','zebra_110'],evidence:'internal-field',evidenceNote:'萬里內部 110Xi4 實機排查紀錄；量測值僅代表該台當時狀態。'
  });

  addRepairKB({
    id:'case-220xi4-drive-belt-tracking-field',brand:'Zebra',models:['220Xi4'],
    title:'【內部實機案例】220Xi4 傳動皮帶越轉越偏：調整件造成側向力',
    category:'內部實機案例／Drive',severity:'已實測',
    summary:'實機傳動皮帶運轉時逐步往單側偏。檢查張力與調整機構後，發現某調整件會持續施加側向力；解除該調整作用後，皮帶不再持續偏移。重點不是照抄「拆某顆螺絲」，而是確認皮帶偏移是否由張力/軸線/調整件導致。',
    keyFacts:['皮帶「越轉越偏」通常應檢查兩軸平行度、張力、軸承/軸套與調整機構，不應只把皮帶換新。','本案例解除一個現場俗稱咖啡色的調整螺絲作用後偏移停止；這是單機結果，不是 220Xi4 原廠固定維修程序。','若調整件原本有結構功能，正式交機前仍需確認固定、張力與安全性，不可留下任意拆除狀態。'],
    engineering:['斷電後先以手轉觀察皮帶是否在每一圈都往同側爬。','檢查 Pulley 是否共平面、軸承是否鬆動、皮帶是否老化變形。','調整張力/軸線時一次只改一項，避免把「剛好不偏」誤當根因已修復。'],
    verify:['手轉多圈皮帶保持中央','低速/高速運轉均不持續爬邊','連續列印後張力與位置穩定','無摩擦粉末、異音或過熱'],
    flow:[['重現皮帶偏移','標記初始位置，手轉/低速觀察是否持續往同一側。',['持續單側偏','無固定方向'],'固定方向較支持幾何/張力。'],['查皮帶與 Pulley','看磨耗、變形、Pulley 共平面與固定。',['正常','發現異常'],'先修明顯異常。'],['查調整/張力機構','確認調整螺絲或張力件是否施加不對稱側向力。',['有影響','無影響'],'本案例有明顯影響。'],['逐項調整並比較','一次只改一項，再觀察多圈。',['偏移停止','仍偏'],'仍偏再查軸承/軸線。'],['完整負載驗證','裝回耗材連續列印，確認不是空載才正常。',['通過','未通過'],'未通過繼續機構排查。']],
    sources:['zebra_xi4'],evidence:'internal-field',evidenceNote:'萬里內部 220Xi4 實機案例；解除特定調整件僅為當次排查結果，不可當通用拆除指示。'
  });

  addRepairKB({
    id:'case-p4650-white-ribbon-field',brand:'Argox',models:['P4-650'],
    title:'【內部實機案例】P4-650＋TR3370 White：提高濃度仍不清楚，20 已出現破碳',
    category:'內部實機案例／白色碳帶',severity:'未完全收斂',
    summary:'客戶使用 P4-650 搭配 TR3370 White，希望白色條碼/文字更清楚。實測低濃度品質不足；提高到 20 已出現局部過熱/破碳，因此不再用「一直加 Darkness」處理。15~16、2 ips 仍未達需求，案例最後建議整機連同紙與碳帶收回檢測。',
    keyFacts:['本案例濃度 13 未破碳、20 已局部破損；這些數字只代表該機＋該紙材＋該碳帶組合。','Zebra 110Xi4 的 Darkness 數值不能直接拿來對照 Argox P4-650。','當提高熱量已造成破碳但品質仍不夠，應轉查耗材匹配、Printhead/Platen 接觸、速度、壓力與機況。'],
    engineering:['曾建議 15~16、2 ips 作為保守測試區間，但客戶仍反映不清楚。','P4-650 現場資訊顯示壓力調整能力與 110Xi4 不同，因此不能用另一機種的壓力/濃度經驗直接套用。','此案例沒有已證實的最終故障零件，應保留「未完全收斂」標記，避免錯誤學習。'],
    verify:['收回整機後以客戶原紙/碳帶建立測試圖','比較清潔前後與 Platen/Head 接觸','確認不同速度/熱量的可用窗口','若換耗材或零件，保留前後樣張'],
    flow:[['固定耗材與測試圖','使用客戶原紙、TR3370 White 與固定內容。',['完成','資料不足'],'避免不同條碼/字型干擾。'],['建立熱量窗口','由安全濃度逐步提高，觀察清晰度與破碳。',['品質改善且不破','先破碳仍不清楚'],'本案例為後者。'],['降低速度交叉','以較低速度測相同熱量。',['改善','仍不足'],'本案例 2 ips 仍不足。'],['停止盲目加熱','出現破碳後轉查 Head/Platen/耗材匹配與機械接觸。',['進硬體檢查','更換耗材比較'],'避免高熱損傷 Head。'],['整機收回檢測','紙與碳帶一起帶回，建立可重現環境。',['待檢測','已收斂'],'本案例原始紀錄停在待深入檢測。']],
    sources:['argox_p4','argox_p4_product'],evidence:'internal-field-open',evidenceNote:'萬里內部 P4-650 白色碳帶測試；最終根因尚未在原始案例中完全收斂。'
  });
})();
;

/* ===== SOURCE: internal-case-library.js ===== */
'use strict';

// 私人 GitHub 共用案例庫（人工確認後才加入）。
// 重要：此檔只保存去識別化維修知識，不保存客戶名稱、完整序號、電話、地址或其他客戶識別資料。
// 新案例由工程師本機產生 submission packet，經人工確認後再由維護者加入此陣列。
(function(){
  const CASES=[
    // 範例格式（正式資料請由提交包轉入，不要直接複製客戶個資）：
    // {
    //   caseId:'case-20260907-zt610-xxxxxxxx',
    //   confirmedAt:'2026-09-07',
    //   brand:'Zebra',model:'ZT610',symptom:'Ribbon Out',
    //   rootCause:'Ribbon Sensor 本體異常',
    //   action:'更換 Ribbon Sensor 並重新校正',
    //   parts:'P/N 依實機序號核對',
    //   verify:'已通過連續列印／冷熱機',
    //   sharedNote:'碳帶存在仍持續 Ribbon Out；Sensor 讀值遮擋前後無合理變化。',
    //   evidence:['拔除 Sensor 後校正可完成','正常件交叉後故障跟著 Sensor 移動']
    // }
  ];

  window.INTERNAL_CASE_LIBRARY=CASES;

  function cleanList(v){return Array.isArray(v)?v.map(x=>String(x||'').trim()).filter(Boolean):[]}
  function addCase(c){
    if(!c||!c.caseId||!c.model||!c.symptom||!c.rootCause||!c.action)return;
    if(window.REPAIR_KB?.some(x=>x.id===`shared-${c.caseId}`))return;
    const facts=[
      `已確認根因：${c.rootCause}`,
      c.parts?`更換／使用零件：${c.parts}`:'未記錄更換料號；若需採購仍須依 Model / S/N / DPI / Revision 核對。',
      ...cleanList(c.evidence)
    ];
    const engineering=[
      `實際處置：${c.action}`,
      c.sharedNote?`案例關鍵觀察：${c.sharedNote}`:'',
      '此案例為內部已確認實機經驗；不可把單台量測數值直接當成同型號通用規格。'
    ].filter(Boolean);
    const verify=[c.verify||'已完修驗證','同症狀再次遇到時，先重現與交叉驗證，不直接依案例盲換零件。'];
    const flow=[
      ['重現相同症狀',`確認 ${c.model} 是否出現「${c.symptom}」且條件與案例相近。`,['相近','不相近'],'不相近時回一般故障流程。'],
      ['先排除低風險因素','先完成耗材、安裝、設定、Calibration 與可視接頭檢查。',['已排除','找到其他原因'],'不要因命中案例就跳過基礎排查。'],
      ['驗證案例根因',`針對「${c.rootCause}」做讀值、線束或已知正常件交叉。`,['根因被支持','不支持','無法交叉'],'只有被支持才進換件。'],
      ['執行維修',c.action,['完成','未完成'],'料號與拆裝仍依該機 Parts/Service 文件。'],
      ['完修回歸',c.verify||'執行冷開機、連印、實際耗材與相關選配驗證。',['通過','未通過'],'未通過不可直接結案。']
    ];
    addRepairKB({
      id:`shared-${c.caseId}`,
      brand:c.brand||'通用',models:[c.model],
      category:'內部實機案例／已確認',severity:'高價值',
      title:`${c.model}｜${c.symptom} → ${c.rootCause}`,
      summary:`已確認內部案例：${c.symptom} 最終收斂為「${c.rootCause}」，處置為「${c.action}」。`,
      keyFacts:facts,engineering,verify,flow,
      sources:[],evidence:'internal-field',
      evidenceNote:`私人 GitHub 共用案例庫｜${c.confirmedAt||'日期未記錄'}｜已去除客戶名稱與完整序號。`,
      internalCaseId:c.caseId
    });
  }

  CASES.forEach(addCase);
  window.registerSharedInternalCase=addCase;
})();
;

/* ===== SOURCE: repair-kb-model-corrections.js ===== */
'use strict';

// 舊批次資料曾以不存在的「iX4-300 Pro」代表 300 dpi iX4 Pro。
// Argox 官方 iX4 Pro 系列實際型號為 iX4-200/240/250/350 Pro；此處在正式資料層修正，避免把錯型號放進搜尋與統計。
(function(){
  const targetIds=new Set([
    'svc-argox-ix4-cutter',
    'argox-ix4-hw-harness',
    'argox-ix4-hw-rewind',
    'argox-ix4-hw-interface',
    'argox-ix4-hw-firmware',
    'argox-ix4-hw-bearing',
    'argox-ix4-hw-peel',
    'argox-ix4-hw-psuload'
  ]);
  const officialModels=['iX4-200 Pro','iX4-240 Pro','iX4-250 Pro','iX4-350 Pro'];
  for(const article of REPAIR_KB){
    if(!targetIds.has(article.id))continue;
    article.models=[...officialModels];
    article.modelCorrection='2026-09-07：移除不存在的 iX4-300 Pro，改為官方 iX4 Pro 型號集合';
  }
})();
;

/* ===== SOURCE: kb-integrity-check.js ===== */
'use strict';

// 維修資料庫完整性自檢：資料量變大後避免重複 ID、錯誤來源、型號拼寫或殘缺流程悄悄混入。
(function(){
  function runKBIntegrityCheck(){
    const list=Array.isArray(window.REPAIR_KB)?window.REPAIR_KB:[];
    const sources=window.KB_SOURCES||{};
    const products=Array.isArray(window.PRODUCTS)?window.PRODUCTS:(typeof PRODUCTS!=='undefined'&&Array.isArray(PRODUCTS)?PRODUCTS:[]);
    const knownModels=new Set(products.map(p=>String(p.m||'').trim()).filter(Boolean));
    const errors=[];
    const warnings=[];
    const seenId=new Map();
    const seenTopic=new Map();
    const brandCount={};
    const categoryCount={};
    const evidenceCount={'A原廠料號':0,'B雙來源料號':0,'內部實機案例':0,'工程SOP':0,'有來源資料':0,'通用工程基線':0};

    list.forEach((x,i)=>{
      const pos=i+1;
      if(!x||typeof x!=='object'){errors.push(`#${pos} 不是有效物件`);return;}
      const tag=x.id||`#${pos}`;
      const ev=String(x.evidence||'');
      if(!x.id)errors.push(`#${pos} 缺少 id`);
      else if(seenId.has(x.id))errors.push(`重複 id：${x.id}（#${seenId.get(x.id)} / #${pos}）`);
      else seenId.set(x.id,pos);
      if(!x.brand)warnings.push(`${tag} 缺少 brand`);else brandCount[x.brand]=(brandCount[x.brand]||0)+1;
      if(!x.category)warnings.push(`${tag} 缺少 category`);else categoryCount[x.category]=(categoryCount[x.category]||0)+1;
      if(!Array.isArray(x.models)||!x.models.length)warnings.push(`${tag} 沒有 models`);
      else for(const m of x.models){if(!m||typeof m!=='string')warnings.push(`${tag} 有無效 model 值`);else if(knownModels.size&&m!=='ALL'&&!knownModels.has(m))warnings.push(`${tag} 的機型不在 catalog：${m}`);}
      if(!x.title)warnings.push(`${tag} 缺少 title`);
      if(!x.summary)warnings.push(`${tag} 缺少 summary`);
      if(!Array.isArray(x.keyFacts)||!x.keyFacts.length)warnings.push(`${tag} 沒有 keyFacts`);
      if(!Array.isArray(x.engineering)||!x.engineering.length)warnings.push(`${tag} 沒有 engineering`);
      if(!Array.isArray(x.verify)||!x.verify.length)warnings.push(`${tag} 沒有 verify`);
      if(!Array.isArray(x.flow)||!x.flow.length)warnings.push(`${tag} 沒有排查流程 flow`);
      else x.flow.forEach((step,si)=>{if(!Array.isArray(step)||step.length<3)errors.push(`${tag} flow 第 ${si+1} 步格式錯誤`);else{if(typeof step[0]!=='string'||!step[0].trim())errors.push(`${tag} flow 第 ${si+1} 步缺少標題`);if(typeof step[1]!=='string'||!step[1].trim())warnings.push(`${tag} flow 第 ${si+1} 步缺少說明`);if(!Array.isArray(step[2])||!step[2].length)warnings.push(`${tag} flow 第 ${si+1} 步沒有結果選項`);}});
      if(!Array.isArray(x.sources)||!x.sources.length){
        if(ev==='oem-parts'||ev==='source-backed'||ev==='verified-b-parts')errors.push(`${tag} 標示為 ${ev} 但沒有來源`);
        else if(!ev.startsWith('internal-field')&&ev!=='workflow-sop')warnings.push(`${tag} 沒有來源；應確認是否只是工程通用基線`);
      }else for(const s of x.sources){if(!sources[s])errors.push(`${tag} 使用不存在的來源代號：${s}`);}

      if(ev==='oem-parts'){
        evidenceCount['A原廠料號']++;
        if(!/料號|P\/N|Parts|Printhead|Platen|Cutter|Sensor|Drive|Electronics|Ribbon|Media Options/i.test([x.title,...(x.keyFacts||[])].join(' ')))warnings.push(`${tag} 標示為原廠料號但內容未見料號/零件資訊`);
      }else if(ev==='verified-b-parts'){
        evidenceCount['B雙來源料號']++;
        const uniqueSources=[...new Set(x.sources||[])];
        if(uniqueSources.length<2)errors.push(`${tag} 為 B 級精確料號但少於兩個獨立來源`);
        if(x.verification!=='dual-source')errors.push(`${tag} 為 B 級精確料號但 verification 不是 dual-source`);
        if(!x.evidenceNote)warnings.push(`${tag} 為 B 級精確料號但缺 evidenceNote`);
        const bCount=uniqueSources.filter(s=>String(sources[s]?.level||'').startsWith('B｜')).length;
        if(bCount<2)warnings.push(`${tag} B 級雙來源中，標示為 B 級的來源少於 2 個；請人工確認來源等級`);
      }else if(ev.startsWith('internal-field')){
        evidenceCount['內部實機案例']++;
        if(!x.evidenceNote)warnings.push(`${tag} 為內部實機案例但缺 evidenceNote`);
        if(x.internalCaseId&&!String(x.id||'').includes(String(x.internalCaseId)))warnings.push(`${tag} 的 internalCaseId 與 id 對應異常`);
      }else if(ev==='workflow-sop'||/SOP|保養|交機|收機|交叉測試|零件採購/.test(x.category||''))evidenceCount['工程SOP']++;
      else if((x.sources||[]).length)evidenceCount['有來源資料']++;
      else evidenceCount['通用工程基線']++;

      const topicKey=[x.brand,(x.models||[]).slice().sort().join('|'),x.title].join('::');
      if(x.title&&seenTopic.has(topicKey))warnings.push(`可能重複主題：${x.title}（${(x.models||[]).join('/')}）`);else if(x.title)seenTopic.set(topicKey,pos);
    });

    window.KB_HEALTH={count:list.length,sourceCount:Object.keys(sources).length,modelCount:knownModels.size,brandCount,categoryCount,evidenceCount,errors,warnings,ok:errors.length===0};
    console.info(`[萬里維修資料庫] ${list.length} 筆｜來源 ${Object.keys(sources).length}｜型號 ${knownModels.size}｜錯誤 ${errors.length}｜警告 ${warnings.length}`);
    console.info('[萬里維修資料庫] 資料組成：',evidenceCount);
    if(warnings.length)console.warn('[萬里維修資料庫] 資料警告：',warnings);
    if(errors.length){
      console.error('[萬里維修資料庫] 完整性錯誤：',errors);
      const box=document.createElement('div');box.id='kbIntegrityAlert';box.style.cssText='max-width:1240px;margin:10px auto;padding:10px 14px;border:1px solid #ef4444;border-radius:10px;background:#fef2f2;color:#991b1b;font-size:12px;font-weight:800';box.textContent=`⚠️ 維修資料庫自檢發現 ${errors.length} 個結構/來源錯誤，請暫停依賴新增資料並查看 Console。`;document.body.insertBefore(box,document.body.firstChild);
    }
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',runKBIntegrityCheck,{once:true});else runKBIntegrityCheck();
})();
;
